import {VERSION,NEEDS,PERSONALITY,SKILLS,GENRES,TRAITS,EMOTIONS,PRIORITIES,ACTIONS,PLACES,DEFAULTS,clamp,round,relationship,chemistry,mood,stamp,addPerson,createWorld,scores,step,removePerson,scenario,restore,log,decide,dominantEmotion,isMember,groupsOf,createGroup,liveSessions,formationPlan,refreshReputation,locationReason,feel,compositionProject,journalEntries,chemistryKnowledge} from './engine.mjs';
import {createPlayback,setPlaybackSpeed,advancePlayback,updatePositions} from './runtime.mjs';
const playback=createPlayback();
const $=q=>document.querySelector(q),$$=q=>[...document.querySelectorAll(q)],esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let world,saveProblem=false,loadFailed=false;try{const saved=localStorage.getItem('garage-vivant-v1');if(saved){const input=JSON.parse(saved);if(input.version!==VERSION){try{if(!localStorage.getItem('garage-vivant-before-v4'))localStorage.setItem('garage-vivant-before-v4',saved);}catch{}}world=restore(input);}else world=createWorld();}catch{world=createWorld();saveProblem=true;loadFailed=true;}
let selected=world.people[0].id,view='map',pair=null,metric='affinity',filter='all',lastUI=0,lastSaved=0,tabInactive=false,labValues=false,rawJournal=false;
const params={drain:['Usure des besoins','Vitesse à laquelle la fatigue et les autres besoins augmentent.'],music:['Attrait de la musique','Poids de la pratique, de la composition et des jams dans les décisions.'],social:['Attrait des rencontres','Poids des activités sociales dans les décisions.'],conflict:['Risque d’accrochage','Amplifie l’effet de l’humeur, de l’impulsivité et des tensions sur les disputes.'],learning:['Apprentissage','Vitesse de progression des compétences musicales.'],randomness:['Spontanéité','Variation ajoutée au score ; 0 donne toujours le choix le mieux coté.'],relations:['Évolution des liens','Amplitude des changements d’affinité, de confiance, de tension et d’amour.'],emotionDecay:['Retour au calme','Vitesse à laquelle les émotions s’atténuent naturellement ; 0 les maintient jusqu’à une nouvelle expérience.'],compositionPace:['Progression des compositions','Vitesse du travail sur les projets. ×1 demande environ quatre à six séances ; ×0 suspend la progression.'],romance:['Avances amoureuses','Fréquence des avances spontanées entre adultes attirés. 0 désactive les avances autonomes.']};
function notify(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').style.display='none',3500);}
function save(){if(loadFailed){$('#save-state').textContent='La sauvegarde illisible a été conservée. Importe un monde valide ou crée explicitement un nouveau quartier.';return;}try{localStorage.setItem('garage-vivant-v1',JSON.stringify(world));saveProblem=false;}catch{saveProblem=true;}$('#save-state').textContent=saveProblem?'Sauvegarde locale indisponible. Exporte le JSON pour conserver ton monde.':'Sauvegarde automatique dans ce navigateur · export JSON disponible.';}
function select(id,open=true){if(!world.people.some(x=>x.id===id))return;selected=id;if(open)$('#inspector').classList.add('open');renderPeople();renderProfile(true);if(view==='journal')renderJournal();if(view==='actions')renderActions();}
function current(){return world.people.find(p=>p.id===selected)||world.people[0];}
function actionLabel(p){const a=p.action;if(!a)return 'Choisit sa prochaine activité';if(a.route.length)return `↗ ${ACTIONS[a.key].label} · en route`;if(a.key==='jam'){const j=world.jams.find(x=>x.id===a.sessionId);return j?.status==='active'?`♬ Jam · ${j.participants.filter(id=>{const q=world.people.find(x=>x.id===id);return q?.action?.sessionId===j.id&&!q.action.route.length;}).length} musiciens`:'♬ Attend un partenaire';}return `${ACTIONS[a.key].icon} ${ACTIONS[a.key].label}`;}
function renderPeople(){$('#population').textContent=world.people.length;$('#people').innerHTML=world.people.map(p=>`<button class="person ${p.id===selected?'active':''}" data-person="${p.id}"><span class="mini-cube" style="background:${esc(p.color)}"></span><span><span class="person-name">${esc(p.name)} ${isMember(world,p)?'<span class="role-dot" title="Membre d’un groupe">♫</span>':''}</span><span class="person-action">${esc(actionLabel(p))}</span></span></button>`).join('');$('#add').disabled=world.people.length>=24;}
function bar(label,value,key=null){return `<div class="need"><span>${esc(label)}</span><div class="bar"><i style="width:${clamp(value)}%;background:${value<25?'#d08c68':value<50?'#b6ab71':'#819b6f'}"></i></div><b ${key?`data-need-value="${key}"`:''}>${round(value)}</b></div>`;}
function spark(p){const h=p.history;if(h.length<2)return '<div class="muted" style="font-size:9px">Historique d’humeur : première mesure après 30 min.</div>';return `<div class="spark-label"><span>Humeur au fil du temps · 0–100</span><span>${stamp(h[0].time)} → ${stamp(h.at(-1).time)}</span></div><svg class="spark" viewBox="0 0 260 32" preserveAspectRatio="none" aria-label="Historique de l’humeur, de 0 à 100"><path d="M0 31H260" stroke="#e8ebdf" fill="none"/><polyline points="${h.map((x,i)=>`${i*260/(h.length-1)},${30-x.mood*.28}`).join(' ')}" fill="none" stroke="#91a786" stroke-width="2"/></svg>`;}
function rangeEditor(group,k,label,v,max=100,min=0){return `<div class="range-row"><label>${esc(label)} <b data-output="${group}:${k}">${round(v)}</b></label><input type="range" min="${min}" max="${max}" value="${v}" data-edit="${group}:${k}" aria-label="${esc(label)}"></div>`;}
function renderProfile(force=false){const p=current();if(!p)return;const openDetails=$$('#profile details[open]'),preserve=openDetails.filter(x=>x.id).map(x=>x.id),catalogScroll=$('#profile-songs .profile-catalog')?.scrollTop||0;const scroll=$('#inspector').scrollTop;if(!force&&($('#profile').contains(document.activeElement)&&['INPUT','SELECT'].includes(document.activeElement.tagName)||openDetails.length)){updateProfile();return;}const a=p.action,candidates=decisionRows(p);const friends=world.people.filter(x=>x!==p).sort((a,b)=>relationship(world,p,b).affinity-relationship(world,p,a).affinity).slice(0,3);
$('#profile').innerHTML=`<div class="profile-head"><div class="portrait" style="background:${esc(p.color)}">♫</div><div><h2>${esc(p.name)}</h2><p>${p.age} ans · ${SKILLS[p.instrument]} · ${p.genre}</p></div></div><div class="pills">${groupsOf(world,p).map(g=>`<button class="pill member" data-open-groups>${esc(g.name)}</button>`).join('')}${p.traits.map(t=>`<span class="pill">${TRAITS[t]}</span>`).join('')}</div><div id="reputation">${reputationHTML(p)}</div><div class="mood"><span>Humeur <span data-mood-word></span></span><strong data-mood>${round(mood(p))}/100</strong></div><div class="action-card"><strong data-action>${esc(actionLabel(p))}</strong><p data-reason>${esc(a?.why)}<br>${a?.route.length?'En déplacement':`${round(a?.remaining||0)} min restantes`} · ${PLACES.find(x=>x.id===a?.dest)?.name||''}</p><div class="bar"><i data-progress style="width:${a?clamp((a.key==='jam'?(world.jams.find(j=>j.id===a.sessionId)?.elapsed||0):a.elapsed)/ACTIONS[a.key].duration*100):0}%"></i></div></div><section><div class="section-head">SES COMPOSITIONS <span id="profile-song-count"></span></div><div id="profile-songs"></div></section><section class="emotion-section"><div class="section-head">CE QUI L’HABITE <span id="emotion-label"></span></div><div id="emotion-bars">${emotionHTML(p)}</div><div id="emotion-source" class="emotion-source"></div></section><section><div class="section-head">BESOINS <span style="color:#8e9888;font-weight:400;letter-spacing:0">100 = comblé</span></div><div id="needs">${Object.entries(NEEDS).map(([k,l])=>bar(l,p.needs[k],k)).join('')}</div><div id="profile-history">${spark(p)}</div></section><section><div class="section-head">POURQUOI CETTE ACTIVITÉ <span id="decision-time" style="letter-spacing:0;font-weight:400"></span></div><div id="ranks">${rankHTML(candidates)}</div><p class="muted" style="font-size:10px;margin:7px 0 0">Ces scores ont servi à choisir l’activité actuelle. La prochaine action sera choisie à la fin, selon la situation à ce moment-là.</p></section><section><div class="section-head">DERNIERS SOUVENIRS</div><div id="memories">${memoryHTML(p)}</div></section><section><div class="section-head">SES 3 PLUS FORTS LIENS <button class="text-button" id="profile-relations">Matrice ↗</button></div>${friends.map(b=>{const r=relationship(world,p,b);return `<button class="person" data-person="${b.id}" style="padding:7px 0"><span class="mini-cube" style="background:${esc(b.color)};width:19px;height:19px"></span><span style="flex:1;font-size:10px">${esc(b.name)}</span><span style="font-size:11px;color:${r.affinity<0?'#c28069':'#819b6f'}">${r.affinity>0?'+':''}${round(r.affinity)}</span></button>`;}).join('')}</section><section><div class="section-head">ACTIVITÉS TERMINÉES <button class="text-button" data-open-actions>Toutes les actions ↗</button></div><div id="profile-counts"></div></section>${priorityEditor(p)}<details id="emotion-edit"><summary>ÉMOTIONS · MODIFIER</summary><p class="muted">Six familles de jeu, trois intensités. Plusieurs émotions peuvent coexister. Les effets nourrissent les prochains choix et compositions.</p>${Object.entries(EMOTIONS).map(([k,v])=>rangeEditor('emotions',k,v.label,p.emotions[k])).join('')}</details><details id="identity-edit"><summary>IDENTITÉ & TRAITS · MODIFIER</summary><div class="editor"><label class="edit-row">Nom<input data-identity="name" maxlength="24" value="${esc(p.name)}"></label><label class="edit-row">Âge<input data-identity="age" type="number" min="18" max="90" value="${p.age}"></label><label class="edit-row">Couleur<input data-identity="color" type="color" value="${esc(p.color)}"></label><label class="edit-row">Instrument<select data-identity="instrument">${Object.entries(SKILLS).filter(([k])=>k!=='writing').map(([k,l])=>`<option value="${k}" ${p.instrument===k?'selected':''}>${l}</option>`).join('')}</select></label><label class="edit-row">Style préféré<select data-identity="genre">${GENRES.map(g=>`<option ${g===p.genre?'selected':''}>${g}</option>`).join('')}</select></label></div><div class="trait-checks" style="margin-top:12px">${Object.entries(TRAITS).map(([k,l])=>`<label><input type="checkbox" data-trait="${k}" ${p.traits.includes(k)?'checked':''}>${l}</label>`).join('')}</div></details><details id="personality-edit"><summary>PERSONNALITÉ · MODIFIER</summary>${Object.entries(PERSONALITY).map(([k,l])=>rangeEditor('personality',k,l,p.personality[k])).join('')}</details><details id="skills-edit"><summary>COMPÉTENCES · MODIFIER</summary>${Object.entries(SKILLS).map(([k,l])=>rangeEditor('skills',k,l,p.skills[k])).join('')}<div class="muted">Chanson en cours : ${round(p.songProgress)} %</div></details><details id="needs-edit"><summary>BESOINS · MODIFIER</summary>${Object.entries(NEEDS).map(([k,l])=>rangeEditor('needs',k,l,p.needs[k])).join('')}</details><details id="intervene"><summary>INTERVENIR</summary><p class="muted">Force une activité, puis laisse l’autonomie reprendre à la fin.</p><div class="file-actions">${Object.entries(ACTIONS).map(([k,v])=>`<button data-force="${k}" style="font-size:10px;padding:7px">${v.icon} ${v.label}</button>`).join('')}<button id="remove" class="danger" style="font-size:10px" ${world.people.length===1?'disabled':''}>Retirer du quartier</button></div></details>`;
for(const id of preserve){const e=$('#'+id);if(e)e.open=true;}$('#inspector').scrollTop=scroll;updateProfile();if($('#profile-songs .profile-catalog'))$('#profile-songs .profile-catalog').scrollTop=catalogScroll;}
function decisionRows(p){const rows=p.action?.decision?.length?p.action.decision:scores(world,p);const top=rows.filter(x=>!x.blocked).slice(0,4);const chosen=rows.find(x=>x.key===p.action?.key);if(chosen&&!top.includes(chosen))top[top.length-1]=chosen;return top;}
function rankHTML(cs){let max=Math.max(1,...cs.map(x=>x.score));const p=current();return cs.map(c=>`<div class="rank ${c.key===p.action?.key?'chosen-rank':''}" title="${esc(c.why)} · base ${c.base} + émotion ${c.emotion}, priorité ×${c.factor}, objectif ×${c.bandBoost}${c.invite?' + invitation '+c.invite:''}"><span>${c.key===p.action?.key?'▸ ':''}${ACTIONS[c.key].icon} ${ACTIONS[c.key].label}</span><div class="bar"><i style="width:${c.score/max*100}%"></i></div><b>${p.action?.mode==='bag'?round(c.chance)+'%':round(c.score)}</b></div>`).join('');}
function emotionHTML(p){return `<div class="emotion-grid">${Object.entries(EMOTIONS).map(([k,e])=>`<div class="emotion-item" title="${e.levels.join(' → ')}"><span style="color:${e.color}">${e.icon} ${e.label}</span><b>${round(p.emotions[k])}</b><div class="bar"><i style="width:${p.emotions[k]}%;background:${e.color}"></i></div></div>`).join('')}</div>`;}
function priorityEditor(p){return `<details id="priorities-edit"><summary>PRIORITÉS · MODIFIER</summary><p class="muted">1 haute · 2 normale · 3 basse · — interdit. L’énergie critique reste prioritaire.</p><div class="editor">${Object.entries(ACTIONS).map(([k,a])=>`<label class="edit-row">${a.icon} ${a.label}<select data-priority="${p.id}:${k}">${priorityOptions(p,k)}</select></label>`).join('')}</div><button data-rethink="${p.id}" style="margin-top:12px">Reconsidérer maintenant</button></details>`;}
function priorityOptions(p,k){return [1,2,3,...(k==='sleep'?[]:[0])].map(v=>`<option value="${v}" ${p.priorities[k]===v?'selected':''}>${v||'—'} · ${PRIORITIES[v]}</option>`).join('');}
function memoryHTML(p){return p.memories.length?p.memories.slice(0,4).map(m=>`<div class="memory ${m.effect<0?'negative':''}"><span>${esc(m.text)}</span><b>${m.effect>0?'+':''}${Math.round(m.effect*10)/10}</b></div>`).join(''):'<div class="muted" style="font-size:10px">Les rencontres laisseront des traces.</div>';}
function updateProfile(){const p=current();if(!p||!$('[data-mood]'))return;const m=round(mood(p));$('[data-mood]').textContent=m+'/100';$('[data-mood-word]').textContent=m>75?'· bien':m<35?'· à plat':'· stable';$('[data-action]').textContent=actionLabel(p);const a=p.action;$('[data-reason]').textContent=`${PLACES.find(x=>x.id===a?.dest)?.name||''} · ${a?.route.length?'Le trajet précède l’activité':a?.key==='jam'&&world.jams.find(j=>j.id===a.sessionId)?.status!=='active'?'La jam attend au moins 2 personnes sur place':round(a?.remaining||0)+' min restantes'}. ${locationReason(world,p)}`;$('[data-progress]').style.width=(a?clamp((a.key==='jam'?(world.jams.find(j=>j.id===a.sessionId)?.elapsed||0):a.elapsed)/ACTIONS[a.key].duration*100):0)+'%';for(const k of Object.keys(NEEDS)){const b=$(`[data-need-value="${k}"]`);if(b){b.textContent=round(p.needs[k]);const i=b.previousElementSibling.firstElementChild;i.style.width=p.needs[k]+'%';i.style.background=p.needs[k]<25?'#d08c68':p.needs[k]<50?'#b6ab71':'#819b6f';}}$('#ranks').innerHTML=rankHTML(decisionRows(p));$('#decision-time').textContent=p.action?stamp(p.action.started||world.time):'À venir';$('#emotion-label').textContent=dominantEmotion(p).label;$('#emotion-bars').innerHTML=emotionHTML(p);const em=dominantEmotion(p),origin=p.emotionSources[em.key]?.[0];$('#emotion-source').innerHTML=em.active&&origin?`<span>Origine récente</span>${esc(origin.text)}`:'Un état qui évolue avec ses expériences.';$('#memories').innerHTML=memoryHTML(p);$('#profile-history').innerHTML=spark(p);$('#reputation').innerHTML=reputationHTML(p);renderProfileSongs(p);$('#profile-counts').innerHTML=Object.entries(ACTIONS).map(([k,a])=>`<div class="count-line"><span>${a.icon} ${a.label}</span><b>${p.actionCounts[k].completed}</b></div>`).join('')+`<p class="muted" style="font-size:9px">Comptées depuis ${stamp(p.countsSince)}.</p>`;}
function reputationHTML(p){const r=p.reputation;return `<div class="reputation-head"><span>Réputation musicale</span><strong>${r.score}<small>/100</small></strong></div><div class="bar"><i style="width:${r.score}%"></i></div><p class="reputation-note">Talent ${r.skill} · catalogue ${r.catalogue} · reconnaissance ${r.recognition} · collaborations ${r.collaboration}. Elle rend ses invitations à jouer plus attirantes.</p>`;}
function projectHTML(p,c=compositionProject(world,p)){if(!c)return '';const progress=clamp(c.work/c.target*100),active=p&&c.id===p.draft.projectId;return `<div class="draft-note"><strong>✎ ${esc(c.title)}</strong><br>${c.status==='idea'?'Idée':c.status==='ready'?'Prête à terminer':'Ébauche'} · ${round(progress)} % · ${c.sessions} séance${c.sessions>1?'s':''}<div class="bar"><i style="width:${progress}%"></i></div><small>${esc(c.genre)} · ${esc(c.tone)} · potentiel provisoire ${c.potential}/100<br>${active?'Le projet reprend à la prochaine séance de composition.':'Projet conservé dans le carnet ; le scénario a lancé un autre projet.'}</small>${c.sources.length?`<details class="causes" data-key="project-${c.id}"><summary>Ce qui inspire ce projet</summary>${c.sources.map(x=>`<p>${esc(x.text)}</p>`).join('')}</details>`:''}</div>`;}
function renderProfileSongs(p){const songs=world.songs.filter(s=>s.authors.includes(p.id));$('#profile-song-count').textContent=`${songs.length} terminée${songs.length>1?'s':''}`;replacePreserving('#profile-songs',`${world.projects.filter(c=>c.author===p.id&&c.status!=='finished').map(c=>projectHTML(p,c)).join('')}${songs.length?`<div class="profile-catalog">${songs.map(song=>`<details class="profile-song" data-key="profile-song-${song.id}"><summary><span>${esc(song.title)}</span><b>${song.quality}/100</b></summary><p>${esc(song.genre)} · ${esc(song.tone)} · ${stamp(song.time)}</p>${song.sources.map(c=>`<p class="muted">${esc(c.text)}</p>`).join('')}</details>`).join('')}</div>`:'<p class="muted">Aucune chanson terminée. Composer crée puis développe un projet visible ici.</p>'}`);}

const sessionStatus={travel:'En route',waiting:'Attend un partenaire',active:'En cours',completed:'Terminée',interrupted:'Interrompue',cancelled:'Annulée'};
function eventHTML(e){if(e.session){const moments=e.events.filter(x=>x.type!=='decision');const place=PLACES.find(x=>x.id===e.place)?.name||'';return `<div class="event ${e.type} session-event" data-entry="${esc(e.id)}"><time>${stamp(e.time)}</time><span class="event-dot"></span><div class="event-body"><button ${e.ids[0]?`data-person="${esc(e.ids[0])}"`:''}><strong>${esc(e.text)}</strong></button><small class="session-meta">${sessionStatus[e.status]} · ${round(e.activeMinutes)} min d’activité · ${esc(place)}${e.end?' · fin '+stamp(e.end):''}</small>${moments.length?`<p class="session-highlight">${esc(moments.filter(x=>x.outcome||x.type==='project').at(-1)?.text||moments.at(-1).text)}</p>`:''}<details class="causes" data-key="session-${esc(e.id)}"><summary>Déroulement et effets (${moments.length})</summary>${e.events.map(x=>`<p><time>${stamp(x.time)}</time> ${esc(x.text)}${x.effects?`<br><b>${esc(x.effects)}</b>`:''}${x.explanation?`<br>${esc(x.explanation)}`:''}${x.repeatFactor<1?`<br>Effet atténué : résultat déjà vécu pendant cette jam.`:''}${x.causes?.map(c=>`<br>Origine : ${esc(c.text)}`).join('')||''}</p>`).join('')||'<p>Le trajet précède l’activité.</p>'}</details></div></div>`;}return `<div class="event ${e.type}" data-entry="event-${e.id}"><time>${stamp(e.time)}</time><span class="event-dot"></span><div class="event-body"><button ${e.ids[0]?`data-person="${esc(e.ids[0])}"`:''}>${esc(e.text)}</button>${e.effects?`<p class="session-highlight">${esc(e.effects)}</p>`:''}${e.causes?.length||e.explanation?`<details data-key="event-${e.id}" class="causes"><summary>Ce qui y a mené</summary>${e.explanation?`<p>${esc(e.explanation)}</p>`:''}${e.causes?.map(c=>`<p><time>${stamp(c.time)}</time> ${esc(c.text)}</p>`).join('')||''}</details>`:''}</div></div>`;}

function replacePreserving(selector,html){const el=$(selector);if(el.innerHTML===html)return;const opened=[...el.querySelectorAll('details[open][data-key]')].map(x=>x.dataset.key),scroll=el.scrollTop,nestedScroll=el.querySelector('.profile-catalog')?.scrollTop||0;const main=el.closest('main'),scroller=main&&getComputedStyle(main).overflowY==='auto'?main:document.scrollingElement;const boundary=scroller===main?main.getBoundingClientRect().top:0;const anchor=scroller.scrollTop>0?[...el.querySelectorAll('[data-entry]')].find(x=>x.getBoundingClientRect().bottom>boundary):null;const anchorKey=anchor?.dataset.entry,anchorTop=anchor?.getBoundingClientRect().top;el.innerHTML=html;for(const d of el.querySelectorAll('details[data-key]'))if(opened.includes(d.dataset.key))d.open=true;el.scrollTop=scroll;if(el.querySelector('.profile-catalog'))el.querySelector('.profile-catalog').scrollTop=nestedScroll;if(anchorKey){const next=[...el.querySelectorAll('[data-entry]')].find(x=>x.dataset.entry===anchorKey);if(next)scroller.scrollTop+=next.getBoundingClientRect().top-anchorTop;}}

function renderMetrics(){let rs=Object.values(world.rels),friends=rs.filter(r=>r.affinity>30).length,tensions=rs.filter(r=>r.tension>25).length;$('#metrics').innerHTML=[['HUMEUR DU QUARTIER',round(world.people.reduce((a,p)=>a+mood(p),0)/world.people.length),'/100'],['LIENS AMICAUX',friends,'orientés'],['TENSIONS',tensions,'liens'],['CHANSONS',world.nextSongId-1,'créées']].map(([l,n,u])=>`<div class="metric"><span>${l}</span><strong>${n} <small>${u}</small></strong></div>`).join('');replacePreserving('#recent',journalEntries(world).filter(e=>e.type!=='decision').slice(0,4).map(eventHTML).join('')||'<div class="empty">Les premières rencontres s’en viennent.</div>');renderGroupStrip();}
function renderMatrix(){const ps=world.people,negative=metric==='tension';$('#relations-view .legend').innerHTML=metric==='chemistry'?`<span class="muted">La chimie est un potentiel symétrique. ${labValues?'Valeurs exactes du laboratoire.':'Elle se découvre par des jams terminées ensemble ; ? = aucune expérience mesurée.'} La complicité et les sentiments restent distincts.</span>`:`<span>${metric==='affinity'?'Hostile':'Faible'}</span><i style="background:#d99883"></i><i style="background:#eee9df"></i><i style="background:${negative?'#d99883':'#82b5a1'}"></i><span>${metric==='affinity'?'Proche':'Forte'}</span><span class="muted">La ligne ressent → la colonne. Les deux points de vue peuvent différer.</span>`;$('#matrix').innerHTML=`<table class="matrix"><thead><tr><th>${metric==='chemistry'?'Potentiel commun':'↓ ressent →'}</th>${ps.map(p=>`<th title="${esc(p.name)}">${esc(p.name.slice(0,8))}</th>`).join('')}</tr></thead><tbody>${ps.map(a=>`<tr><th>${esc(a.name.slice(0,10))}</th>${ps.map(b=>{if(a===b)return '<td style="text-align:center;color:#bfc4b8">—</td>';const k=chemistryKnowledge(world,a,b);if(metric==='chemistry'&&!labValues){const grade=k.known?k.grade:'?',color=!k.known?'#eeeee7':k.grade==='Très prometteuse'?'#d3e6cb':k.grade==='Prometteuse'?'#e1ead4':k.grade==='Contrastée'?'#eee4d3':'#ebd4ca';return `<td><button class="chemistry-grade ${pair?.[0]===a.id&&pair?.[1]===b.id?'chosen':''}" data-pair="${a.id},${b.id}" style="background:${color}" title="${esc(grade)} · ${k.confidence} · ${k.sessions} jams communes">${k.known?grade:'?'}</button></td>`;}const r=relationship(world,a,b),v=metric==='chemistry'?chemistry(a,b):r[metric],intensity=metric==='affinity'?Math.abs(v)/100:v/100,red=metric==='tension'||metric==='affinity'&&v<0,bg=red?`rgba(199,114,82,${.08+intensity*.65})`:`rgba(83,147,113,${.06+intensity*.65})`;return `<td><button class="${pair?.[0]===a.id&&pair?.[1]===b.id?'chosen':''}" data-pair="${a.id},${b.id}" style="background:${bg}" title="${esc(a.name)} → ${esc(b.name)} : ${round(v)}">${round(v)}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table>`;}

function renderPair(){if(!pair){$('#relation-detail').innerHTML='<div class="empty">Sélectionne un lien dans la matrice pour l’examiner.</div>';return;}let a=world.people.find(p=>p.id===pair[0]),b=world.people.find(p=>p.id===pair[1]);if(!a||!b){pair=null;renderPair();return;}$('#relation-detail').innerHTML=`<h2 class="pair-title">${esc(a.name)} & ${esc(b.name)}</h2><p class="muted">Chimie potentielle : ${labValues?round(chemistry(a,b))+'/100':esc(chemistryKnowledge(world,a,b).grade)+' · '+chemistryKnowledge(world,a,b).confidence} (${chemistryKnowledge(world,a,b).sessions} jams communes) · ${a.genre===b.genre?'Style musical partagé':'Styles musicaux différents'} · ${a.instrument!==b.instrument?'Instruments complémentaires':'Même instrument'}</p><div class="pair-directions">${[[a,b],[b,a]].map(([p,q])=>{let r=relationship(world,p,q);return `<div><h3>${esc(p.name)} → ${esc(q.name)}</h3>${Object.entries({affinity:'Affinité',trust:'Confiance',tension:'Tension',collaboration:'Complicité musicale',attraction:'Attirance',love:'Amour vécu'}).map(([k,l])=>`<div class="range-row"><label>${l} <b data-rel-output="${p.id}:${q.id}:${k}">${round(r[k])}</b></label><input type="range" data-rel="${p.id}:${q.id}:${k}" aria-label="${l} de ${esc(p.name)} envers ${esc(q.name)}" min="${k==='affinity'?-100:0}" max="100" value="${r[k]}"></div>`).join('')}<p class="muted">${r.meetings} interactions · dernier contact ${r.meetings?stamp(r.last):'jamais'}</p></div>`;}).join('')}</div>`;}
function renderJournal(){const es=journalEntries(world,{raw:rawJournal,filter,selected});replacePreserving('#journal',es.slice(0,150).map(eventHTML).join('')||'<div class="empty">Aucun événement dans ce filtre pour le moment.</div>');$('#song-count').textContent=world.songs.length+' terminées';replacePreserving('#projects',world.projects.filter(c=>c.status!=='finished').map(c=>{const p=world.people.find(x=>x.id===c.author);return `<div class="project-card"><button class="text-button" ${p?`data-person="${p.id}"`:''}>${esc(p?.name||'Ancien voisin')} ↗</button>${projectHTML(p,c)}</div>`;}).join('')||'<p class="muted">Les projets apparaissent dès qu’un personnage commence à composer.</p>');replacePreserving('#songs',world.songs.map(s=>`<div class="song"><div class="song-title">♫ ${esc(s.title)} ${s.hit?'<span class="pill member">Ça résonne !</span>':''}<strong>${s.quality}/100</strong></div><small>${esc(s.genre)} · ${s.authors.map(id=>world.people.find(p=>p.id===id)?.name||'Ancien voisin').map(esc).join(', ')} · ${stamp(s.time)}</small><div class="song-tone"><span style="color:${EMOTIONS[s.emotion]?.color||'#819b6f'}">${EMOTIONS[s.emotion]?.icon||'♫'} ${esc(s.tone)} · intensité ${s.intensity}/100</span><span>Écho public ${s.resonance===null?'non mesuré':s.resonance+'/100'}</span></div><details class="causes" data-key="song-${s.id}"><summary>Les expériences derrière la chanson</summary>${s.sources?.length?s.sources.map(c=>`<p><time>${stamp(c.time)}</time> ${esc(c.text)}</p>`).join(''):'<p>Pas d’événement émotionnel marqué pendant cette composition.</p>'}${s.breakdown?`<p>Qualité : maîtrise ${s.breakdown.craft} + expression ${s.breakdown.expression} + ensemble ${s.breakdown.ensemble} + perfectionnisme ${s.breakdown.perfection} + variation ${s.breakdown.variance} − surcharge émotionnelle ${s.breakdown.overwhelm}. Les arrondis peuvent varier d’un point.</p>`:''}<p>La tonalité conserve les émotions de la première phase créative ; les séances suivantes développent la chanson. L’écho public est un indicateur simulé.</p></details></div>`).join('')||'<div class="empty">Plusieurs séances de composition font avancer un projet jusqu’à une chanson terminée. Les projets en cours sont visibles ci-dessus.</div>');}
function renderSettings(){$('#decision-mode').value=world.decisionMode;$('#parameters').innerHTML=Object.entries(params).map(([k,[l,d]])=>`<div class="range-row"><label>${l} <b data-param-output="${k}">×${world.params[k].toFixed(1)}</b></label><input type="range" min="0" max="3" step="0.1" value="${world.params[k]}" data-param="${k}" aria-label="${l}"><p>${d}</p></div>`).join('');$('#scenario-current').textContent='Scénario actuel : '+world.scenario;$('#save-state').textContent=saveProblem?'Sauvegarde locale indisponible. Exporte ton monde en JSON.':'Sauvegarde automatique dans ce navigateur.';}
const titles={actions:['Ce qu’ils peuvent faire.','Sept actions, leurs effets et leurs compteurs.'],groups:['Les groupes qui se forment.','Des liens deviennent des projets communs. Plusieurs groupes peuvent se croiser.'],map:['Une banlieue. '+world.people.length+' univers.','La vie se passe entre deux répétitions. Action à droite du cube · émotion à gauche.'],relations:['Le courant passe. Ou pas.','Des liens vécus, des affinités et quelques fausses notes.'],journal:['Les petites histoires du quartier.','Chaque décision, chaque rencontre, chaque chanson.'],settings:['Change les règles du quotidien.','Observe les conséquences. Ajuste. Recommence.']};
function changeView(v){view=v;for(const el of $$('.view'))el.hidden=el.id!==v+'-view';for(const el of $$('nav button'))el.classList.toggle('active',el.dataset.view===v);$('#view-title').textContent=v==='map'?`Une banlieue. ${world.people.length} univers.`:titles[v][0];$('#view-subtitle').textContent=titles[v][1];if(v==='relations'){renderMatrix();renderPair();}if(v==='journal')renderJournal();if(v==='settings')renderSettings();if(v==='groups')renderGroups();if(v==='actions')renderActions();if(v==='map')updatePositions(world.people,displayPos,{visible:false});}
function render(){ $('#clock').textContent=stamp(world.time);$('#pause').textContent=playback.speed>0?'Ⅱ Pause':'▶ Jouer';$('#speed').value=playback.speed;$('#speed-value').textContent=playback.speed===0?'Pause':'×'+playback.speed.toLocaleString('fr-CA');$('#status').textContent=playback.speed>0?'Autonomie active':'Simulation en pause';renderPeople();renderProfile();renderMetrics();if(view==='groups')renderGroups();if(view==='actions')renderActions();if(view==='relations'&&!$('#relations-view').contains(document.activeElement)){renderMatrix();if(!['INPUT','SELECT'].includes(document.activeElement.tagName))renderPair();}if(view==='journal')renderJournal();}
function modal(html){$('#dialog-content').innerHTML=html;$('#dialog').showModal();}
$('#dialog-close').onclick=()=>$('#dialog').close();$('#help').onclick=()=>modal('<h2>Bienvenue rue des Érables.</h2><p>Les cubes décident seuls. Clique un voisin pour voir ce qu’il fait, ce dont il a besoin et pourquoi il choisit son activité.</p><p><b>Quartier</b> : les trajets et les rencontres. <b>Relations</b> : les sentiments de chacun envers chacun. <b>Journal</b> : les événements. <b>Réglages</b> : le moteur et les scénarios.</p><p>Dans la fiche, ouvre les sections « modifier » pour changer un personnage. « Intervenir » te permet de forcer une activité. Le curseur règle la vitesse de 0 à 10 par pas de 0,1 ; 0 met en pause. +1 h avance d’une heure puis reste en pause. À ×1, une seconde réelle vaut 8 minutes simulées.</p><p>Actions expose les activités, leurs compteurs et les priorités. Groupes montre les formations qui émergent des relations, avec plusieurs appartenances possibles. Six émotions se propagent dans les décisions, les relations et la composition. Les événements et les chansons exposent leurs causes. Les jams démarrent à deux sur place. Leurs participants sont surlignés. Composer fait avancer une idée puis une ébauche persistante. Plusieurs séances terminent une chanson. Le journal regroupe les sessions ; ses détails exposent les causes. La chimie se découvre après des jams communes, avec une option de valeurs exactes au laboratoire. Les cubes restent devant les bâtiments pour être visibles. Pas d’audio pour le moment.</p>');
function setSpeed(value){setPlaybackSpeed(playback,value);render();if(playback.speed===0)updatePositions(world.people,displayPos,{visible:false});}
$('#pause').onclick=()=>setSpeed(playback.speed>0?0:playback.resumeSpeed);$('#speed').oninput=e=>setSpeed(e.target.value);$('#step').onclick=()=>{setPlaybackSpeed(playback,0);step(world,60);updatePositions(world.people,displayPos,{visible:false});render();save();};$('#nav').onclick=e=>{if(e.target.dataset.view)changeView(e.target.dataset.view);};$('#all-events').onclick=()=>changeView('journal');$('#close-inspector').onclick=()=>$('#inspector').classList.remove('open');$('#add').onclick=()=>{const p=addPerson(world);if(p){decide(world,p);select(p.id);render();changeView(view);save();}};
$('#lab-values').onchange=e=>{labValues=e.target.checked;renderMatrix();renderPair();};$('#raw-journal').onchange=e=>{rawJournal=e.target.checked;renderJournal();};$('#relation-metric').onchange=e=>{metric=e.target.value;renderMatrix();};$('#event-filter').onchange=e=>{filter=e.target.value;renderJournal();};
document.addEventListener('click',e=>{const person=e.target.closest('[data-person]');if(person)select(person.dataset.person);const cell=e.target.closest('[data-pair]');if(cell){pair=cell.dataset.pair.split(',');renderPair();renderMatrix();}const force=e.target.closest('[data-force]');if(force){decide(world,current(),force.dataset.force);renderProfile(true);save();}if(e.target.id==='profile-relations'){changeView('relations');}if(e.target.id==='remove'&&world.people.length>1){removePerson(world,selected);selected=world.people[0].id;pair=null;render();renderProfile(true);save();}const sc=e.target.closest('[data-scenario]');if(sc){scenario(world,sc.dataset.scenario);if(sc.dataset.scenario==='Cœur brisé')selected=world.people[0].id;renderSettings();renderProfile(true);render();save();notify('Scénario appliqué : '+sc.dataset.scenario);}});
document.addEventListener('input',e=>{const el=e.target,p=current();if(el.dataset.edit){const [group,k]=el.dataset.edit.split(':');p[group][k]=Number(el.value);$(`[data-output="${group}:${k}"]`).textContent=round(Number(el.value));updateProfile();}if(el.dataset.identity){const k=el.dataset.identity;p[k]=k==='age'?clamp(Number(el.value),18,90):el.value;renderPeople();}if(el.dataset.param){const k=el.dataset.param;world.params[k]=Number(el.value);$(`[data-param-output="${k}"]`).textContent='×'+world.params[k].toFixed(1);}if(el.dataset.rel){const [a,b,k]=el.dataset.rel.split(':');const r=relationship(world,world.people.find(p=>p.id===a),world.people.find(p=>p.id===b));r[k]=Number(el.value);$(`[data-rel-output="${a}:${b}:${k}"]`).textContent=round(r[k]);renderMatrix();}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.trait){const p=current(),t=el.dataset.trait;p.traits=el.checked?[...new Set([...p.traits,t])]:p.traits.filter(x=>x!==t);renderProfile(true);}if(el.dataset.edit||el.dataset.identity||el.dataset.param||el.dataset.rel||el.dataset.trait){const ev=log(world,'system','Paramètre modifié manuellement.',el.dataset.edit||el.dataset.identity||el.dataset.trait?[selected]:[]);if(el.dataset.edit?.startsWith('skills:')||el.dataset.identity==='instrument')refreshReputation(world,current());if(el.dataset.edit?.startsWith('emotions:')){const key=el.dataset.edit.split(':')[1];ev.text=`Intervention : ${EMOTIONS[key].label.toLowerCase()} de ${current().name} réglée à ${round(current().emotions[key])}.`;current().emotionSources[key]=[{id:ev.id,time:ev.time,text:ev.text}];}save();}});
$('#export').onclick=()=>{save();const blob=new Blob([JSON.stringify(world,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`garage-vivant-j${Math.floor(world.time/1440)+1}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);notify('Monde exporté avec son état complet.');};$('#import').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>50000000)throw Error('Fichier trop volumineux.');let candidate=restore(JSON.parse(await f.text()));world=candidate;loadFailed=false;displayPos.clear();selected=world.people[0].id;pair=null;setPlaybackSpeed(playback,0);renderProfile(true);changeView(view);render();save();notify('Monde importé. Simulation en pause.');}catch(err){notify('Import refusé : '+err.message);}e.target.value='';};
$('#reset').onclick=()=>modal('<h2>Un nouveau quartier</h2><p>Remplace le monde actuel. Exporte le JSON si tu veux le conserver. La même graine reproduit le même départ.</p><label>Graine<input id="seed" type="number" value="2040" min="0" max="4294967295"></label><label>Voisins<input id="count" type="number" value="8" min="2" max="24"></label><button id="confirm-reset" class="primary">Créer le quartier</button>');document.addEventListener('click',e=>{if(e.target.id==='confirm-reset'){loadFailed=false;world=createWorld(clamp(Number($('#seed').value),0,4294967295),clamp(round(Number($('#count').value)),2,24));displayPos.clear();selected=world.people[0].id;pair=null;setPlaybackSpeed(playback,1);$('#dialog').close();renderProfile(true);changeView(view);render();save();}});
function renderGroupStrip(){const sessions=liveSessions(world);$('#band-strip').innerHTML=`<div><span class="eyebrow">LE QUARTIER ENSEMBLE</span><strong>${world.groups.length} groupe${world.groups.length>1?'s':''} · ${sessions.filter(x=>x.type==='jam').length} jam${sessions.filter(x=>x.type==='jam').length>1?'s':''} en cours</strong><small>${sessions.length?sessions.map(x=>`${esc(x.label)} (${x.participants.length})`).join(' · '):'Les rencontres font naître les projets.'}</small></div><button data-open-groups>Voir les groupes ↗</button>`;}
function renderActions(){const p=current();$('#action-person-name').textContent=p.name;if(!$('#actions-view').contains(document.activeElement)||!['INPUT','SELECT'].includes(document.activeElement.tagName)){$('#action-catalog').innerHTML=Object.entries(ACTIONS).map(([k,a])=>{const c=p.actionCounts[k],blocked=k==='form'&&!formationPlan(world,p);return `<div class="action-entry"><span class="action-symbol">${a.icon}</span><div><h3>${a.label}</h3><p>${a.description}</p><small>${a.duration} min d’activité · ${c.completed} terminée${c.completed>1?'s':''} · ${c.started} lancée${c.started>1?'s':''} · ${c.interrupted} interrompue${c.interrupted>1?'s':''}</small>${blocked?'<small>Pas de nouveau partenaire admissible pour le moment.</small>':''}</div><button data-force="${k}" ${blocked?'disabled':''}>Lancer</button></div>`;}).join('');$('#priority-table').innerHTML=`<table class="priorities"><thead><tr><th>Personnage</th>${Object.values(ACTIONS).map(a=>`<th>${a.icon}<small>${a.label}</small></th>`).join('')}</tr></thead><tbody>${world.people.map(q=>`<tr><th><button data-person="${q.id}">${esc(q.name)}</button></th>${Object.keys(ACTIONS).map(k=>`<td><select class="priority-${q.priorities[k]}" data-priority="${q.id}:${k}" aria-label="${ACTIONS[k].label} pour ${esc(q.name)}">${priorityOptions(q,k)}</select></td>`).join('')}</tr>`).join('')}</tbody></table>`;}
$('#location-guide').innerHTML='<p class="muted"><b>Maison →</b> se reposer. <b>Garages →</b> pratiquer, composer et jammer. <b>Café, parc et disquaire →</b> rencontrer des voisins. <b>Parc →</b> décrocher. Former un groupe mène vers le partenaire choisi.</p><p class="muted">Le personnage choisit d’abord une activité, puis un lieu adapté. Le trajet ne compte pas comme du temps d’activité. Pour un jam, tous les participants reçoivent le même rendez-vous ; la session commence quand au moins deux sont arrivés.</p>';
}
function renderGroups(){replacePreserving('#group-list',world.groups.length?world.groups.map(g=>`<article class="panel group-card" id="group-${g.id}"><div class="section-head"><span>${esc(g.genre)} · ${g.members.length} membres</span><span>${stamp(g.created)}</span></div><h2>${esc(g.name)}</h2><div class="group-members">${g.members.map(id=>{const p=world.people.find(x=>x.id===id);return `<button data-person="${id}"><span class="mini-cube" style="background:${p.color}"></span><span><b>${esc(p.name)}</b><small>${SKILLS[p.instrument]} · réputation ${p.reputation.score}</small></span></button>`;}).join('')}</div><p class="muted">${g.origin==='migration'?'Groupe conservé de la version précédente.':g.origin==='laboratoire'?'Créé manuellement dans le laboratoire.':'Né des liens entre '+g.founders.map(id=>world.people.find(p=>p.id===id)?.name||'un ancien voisin').map(esc).join(' et ')+'.'} Les membres peuvent appartenir à d’autres groupes.</p></article>`).join(''):'<div class="panel empty">Aucun groupe pour l’instant. Laisse les musiciens jammer et se rapprocher : les liens réciproques peuvent déclencher « Former un groupe ».</div>');}
$('#decision-mode').onchange=e=>{world.decisionMode=e.target.value;log(world,'system',`Décisions : ${world.decisionMode==='bag'?'sac pondéré':'meilleur score'}.`);save();notify('Mode appliqué aux prochaines décisions.');};
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.priority){const [id,k]=el.dataset.priority.split(':');const p=world.people.find(p=>p.id===id);p.priorities[k]=Number(el.value);el.className='priority-'+el.value;log(world,'system',`Priorité de ${p.name} : ${ACTIONS[k].label.toLowerCase()} → ${PRIORITIES[el.value].toLowerCase()}.`,[id]);save();}});
document.addEventListener('click',e=>{if(e.target.closest('[data-open-groups]'))changeView('groups');if(e.target.closest('[data-open-actions]'))changeView('actions');const rethink=e.target.closest('[data-rethink]');if(rethink){const p=world.people.find(p=>p.id===rethink.dataset.rethink);decide(world,p);renderProfile(true);save();}if(e.target.id==='reset-priorities'){for(const p of world.people)for(const k of Object.keys(ACTIONS))p.priorities[k]=2;renderActions();log(world,'system','Les priorités reviennent à la normale.');save();}if(e.target.id==='create-group'){modal(`<h2>Créer un groupe · laboratoire</h2><p>Intervention manuelle : choisis au moins deux membres. Ils conservent leurs autres groupes. La formation autonome reste active.</p><label>Nom <input id="group-name" maxlength="50" placeholder="Nom facultatif" style="width:70%"></label><div class="group-select">${world.people.map(p=>`<label><input type="checkbox" name="group-member" value="${p.id}" ${p.id===selected?'checked':''}> ${esc(p.name)} · ${SKILLS[p.instrument]}</label>`).join('')}</div><button id="confirm-group" class="primary">Créer</button>`);}if(e.target.id==='confirm-group'){const ids=$$('input[name="group-member"]:checked').map(x=>x.value);if(ids.length<2){notify('Choisis au moins deux musiciens.');return;}createGroup(world,ids,{name:$('#group-name').value.trim()||null,manual:true});$('#dialog').close();renderGroups();renderProfile(true);renderGroupStrip();save();}});
// A small, entirely code-drawn town. No external assets or dependencies.
const canvas=$('#map'),ctx=canvas.getContext('2d');let screenPositions=[],displayPos=new Map();
function rect(x,y,w,h,c,r=0){ctx.fillStyle=c;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
function label(text,x,y,color='#586b53',size=11){ctx.fillStyle=color;ctx.font=`${size}px ui-sans-serif, system-ui`;ctx.textAlign='center';ctx.fillText(text,x,y);}
function tree(x,y,r=17){rect(x-2,y,4,17,'#929d76',2);ctx.fillStyle='#cbd8b9';ctx.beginPath();ctx.arc(x+2,y+5,r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b1c59c';ctx.beginPath();ctx.arc(x-3,y,r*.8,0,Math.PI*2);ctx.fill();}
function draw(){let width=canvas.clientWidth,height=canvas.clientHeight,dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(width*dpr)||canvas.height!==Math.round(height*dpr)){canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,width,height);let scale=Math.min(width/1100,height/670),ox=(width-1100*scale)/2,oy=(height-670*scale)/2;ctx.translate(ox,oy);ctx.scale(scale,scale);rect(0,0,1100,670,'#e8ecdc');ctx.fillStyle='#d9e1cd';for(let i=0;i<140;i++){let x=(i*137+31)%1100,y=(i*89+71)%670;rect(x,y,2,2,'#d5dec6');}rect(0,290,1100,100,'#ced2c6');rect(0,310,1100,60,'#babeb7');rect(0,292,1100,4,'#eef0e5');rect(0,384,1100,4,'#eef0e5');ctx.strokeStyle='#e5e6d9';ctx.lineWidth=2;ctx.setLineDash([18,20]);ctx.beginPath();ctx.moveTo(0,340);ctx.lineTo(1100,340);ctx.stroke();ctx.setLineDash([]);label('R U E   D E S   É R A B L E S',550,345,'#909789',9);
for(const pl of PLACES){const {x,y,w,h,color}=pl;rect(pl.door.x-15,Math.min(pl.door.y,290),30,Math.abs(pl.door.y-290)+(pl.door.y>340?50:0),'#d5dac9');if(pl.kind==='park'){rect(x-12,y-8,w+24,h+10,'#d8e3c7',18);tree(x+30,y+35,27);tree(x+w-30,y+40,23);tree(x+90,y+105,19);rect(x+112,y+38,55,10,'#a7a188',3);rect(x+125,y+65,36,26,'#c4c0a3',5);label('PARC DES AMPLIS',x+w/2,y+h+19,'#6b7d5c',11);continue;}rect(x+7,y+9,w,h,'#b6c1a238',8);rect(x,y,w,h,color,7);rect(x,y,w,20,'#00000012',7);rect(x+12,y+28,w-24,h-40,'#ffffff16',3);if(pl.kind==='garage'){rect(x+28,y+55,w-56,62,'#edeadf',3);for(let j=0;j<4;j++)rect(x+28,y+64+j*12,w-56,1,'#cccec3');rect(x+62,y+41,w-124,12,'#567061',3);label(pl.id==='g1'?'01':'02',x+w-22,y+38,'#586b53',10);}else if(pl.kind==='home'){for(let j=0;j<3;j++){rect(x+15+j*64,y+37,51,73,'#e8e1d3',3);rect(x+22+j*64,y+45,14,20,'#a4b9b2',2);rect(x+39+j*64,y+76,16,34,'#b2a18e',2);}}else{for(let j=0;j<3;j++)rect(x+20+j*55,y+45,39,36,'#edf0d7',2);rect(x+20,y+89,w-40,10,color,2);label(pl.kind==='cafe'?'CHEZ JO':'DISQUES',x+w/2,y+32,'#6b6659',11);}label(pl.name,pl.door.x,pl.door.y+(pl.door.y<340?31:-25),'#64745b',11);}
[[40,120],[360,105],[697,185],[1020,126],[47,470],[330,522],[735,505],[1030,550],[340,240],[1030,260],[55,600],[1060,60]].forEach(([x,y])=>tree(x,y));rect(340,276,40,7,'#9f9f83',3);rect(690,400,40,7,'#9f9f83',3);label('QUARTIER DES MUSICIENS',550,625,'#8f9c80',9);
// Shared activity highlights represent actual concurrent activity, not mere proximity.
for(const session of liveSessions(world)){const positions=session.participants.map(id=>displayPos.get(id)).filter(Boolean);if(positions.length<2)continue;const minX=Math.min(...positions.map(p=>p.x))-22,maxX=Math.max(...positions.map(p=>p.x))+22,minY=Math.min(...positions.map(p=>p.y))-27,maxY=Math.max(...positions.map(p=>p.y))+9;const color=session.type==='jam'?'#9a83b7':'#649b83';rect(minX,minY,maxX-minX,maxY-minY,color+'26',13);ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(minX,minY,maxX-minX,maxY-minY,13);ctx.stroke();ctx.setLineDash([4,4]);ctx.beginPath();positions.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();ctx.setLineDash([]);const text=session.label+' · '+positions.length,center=(minX+maxX)/2;ctx.font='11px ui-sans-serif, system-ui';const w=Math.min(275,ctx.measureText(text).width+18);rect(center-w/2,minY-24,w,19,'#fffef4eb',5);label(text,center,minY-11,color,10);}
if($('#links').checked){for(let i=0;i<world.people.length;i++)for(let j=i+1;j<world.people.length;j++){const a=world.people[i],b=world.people[j],r=relationship(world,a,b),r2=relationship(world,b,a);let affinity=(r.affinity+r2.affinity)/2,tension=Math.max(r.tension,r2.tension);if(Math.abs(affinity)<12&&tension<15)continue;const pa=displayPos.get(a.id),pb=displayPos.get(b.id);ctx.strokeStyle=Math.max(r.love,r2.love)>15?'#be7d9caa':tension>25||affinity<0?'#ca866299':'#75977888';ctx.lineWidth=a.id===selected||b.id===selected?2:1;ctx.setLineDash(tension>25?[5,4]:[]);ctx.beginPath();ctx.moveTo(pa.x,pa.y-10);ctx.lineTo(pb.x,pb.y-10);ctx.stroke();ctx.setLineDash([]);}}
if($('#paths').checked){const p=current(),pos=displayPos.get(p.id);ctx.strokeStyle='#788c6988';ctx.lineWidth=2;ctx.setLineDash([4,5]);ctx.beginPath();ctx.moveTo(pos.x,pos.y);p.action?.route.forEach(r=>ctx.lineTo(r.x,r.y));ctx.stroke();ctx.setLineDash([]);}
screenPositions=[];for(const p of [...world.people].sort((a,b)=>a.y-b.y)){let pos=displayPos.get(p.id),x=pos.x,y=pos.y;let isSelected=p.id===selected,size=isSelected?23:19;ctx.fillStyle='#82916828';ctx.beginPath();ctx.ellipse(x,y+4,16,5,0,0,Math.PI*2);ctx.fill();if(isSelected){ctx.strokeStyle='#476f4e';ctx.lineWidth=1.5;ctx.beginPath();ctx.ellipse(x,y+3,22,9,0,0,Math.PI*2);ctx.stroke();}rect(x-size/2,y-size,size,size,p.color,3);rect(x-size/2,y-size,size,5,'#ffffff38',3);rect(x+size/2-5,y-size+4,5,size-4,'#00000015',2);if(isMember(world,p)){rect(x-size/2,y-2,size,3,'#fff8d2');}rect(x-5,y-11,2,2,'#ffffff');rect(x+3,y-11,2,2,'#ffffff');if(p.action){ctx.fillStyle='#f9fbf0ed';ctx.beginPath();ctx.arc(x+17,y-30,10,0,Math.PI*2);ctx.fill();const em=dominantEmotion(p);label(p.action.route.length?'↗':ACTIONS[p.action.key].icon,x+17,y-26,'#66805a',12);if($('#emotional-map').checked&&em.active){rect(x-30,y-42,20,18,'#f9fbf0ed',6);label(EMOTIONS[em.key].icon,x-20,y-29,EMOTIONS[em.key].color,12);}}const tw=ctx.measureText(p.name).width;rect(x-tw/2-6,y+10,tw+12,16,isSelected?'#fffcf4ed':'#f1f5e5cc',3);label(p.name,x,y+21,isSelected?'#365740':'#6f7b62',10);screenPositions.push({id:p.id,x:ox+x*scale,y:oy+(y-9)*scale,r:Math.max(15,size*scale)});}
const hour=world.time%1440/60;if(hour>=21||hour<6){rect(0,0,1100,670,'#25395426');$('#weather').textContent='☾ Une autre nuit de musique';}else $('#weather').textContent=hour<12?'☀ Un beau matin en banlieue':hour<18?'☀ Le quartier prend son rythme':'◐ La fin de journée s’étire';}
canvas.addEventListener('click',e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;const hits=screenPositions.filter(p=>Math.hypot(p.x-x,p.y-y)<p.r+10).sort((a,b)=>Math.hypot(a.x-x,a.y-y)-Math.hypot(b.x-x,b.y-y));if(hits.length)select(hits[0].id);});
document.addEventListener('visibilitychange',()=>{tabInactive=document.hidden;playback.budget=0;playback.last=performance.now();updatePositions(world.people,displayPos,{visible:false});save();});window.addEventListener('pagehide',save);
function frame(now){const dt=advancePlayback(playback,now,!tabInactive,minutes=>step(world,minutes));updatePositions(world.people,displayPos,{visible:view==='map'&&!tabInactive,paused:playback.speed===0,dt});if(now-lastUI>700){render();lastUI=now;}if(now-lastSaved>12000){save();lastSaved=now;}if(view==='map')draw();requestAnimationFrame(frame);}
renderPeople();renderProfile(true);renderSettings();render();requestAnimationFrame(frame);if(saveProblem)notify('Sauvegarde locale non disponible ou incompatible ; nouveau quartier chargé.');
